contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        // The reference contract should return false for an account that was never granted the role.
        // The mutant always returns true, so grant-untouched accounts violate the rule.
        bool hasRoleRef = c.hasRole(role, account);
        bool pending = c.isOperationPending(role);
        // Ensure the fuzzed role is not an already-granted role from the constructor setup.
        // The constructor grants TIMELOCK_ADMIN_ROLE to address(this) and to the timelock itself.
        vm.assume(account != address(this));
        vm.assume(account != address(c));
        vm.assume(role != 0x00); // DEFAULT_ADMIN_ROLE auto-admin setup may interfere
        // The rule: if an account has never been granted the role (not pending, not setup), hasRole must be false.
        // Equivalent to checking that hasRole returns false when the role was not granted explicitly.
        // Since we cannot observe internal state directly, we rely on the fact that C's hasRole returns true
        // only for explicitly granted roles. The mutant always returns true, breaking this for any ungranted role+account.
        assertTrue(!hasRoleRef, "mutant would return true");
    }
}

