pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Deploy with empty proposers and executors arrays
        address[] memory proposers = new address[](0);
        address[] memory executors = new address[](0);
        c = new C(0, proposers, executors);
    }
    function testFuzz_property(bytes32 role, address account) public {
        // Admissible domain: role must not be the default admin role,
        // and account must not be the timelock itself (to avoid self-administration bypass)
        vm.assume(role != c.DEFAULT_ADMIN_ROLE());
        vm.assume(account != address(c));

        // Ensure the caller (this contract) has the admin role so it can grant sub-roles
        // C's constructor grants TIMELOCK_ADMIN_ROLE to the deployer (address(this))
        // We also need to become admin of the specific role we intend to grant.
        // The default admin is bytes32(0), so we cannot set admin for arbitrary roles.
        // We'll use the known admin roles.
        bytes32 executorRole = c.EXECUTOR_ROLE();
        bytes32 proposerRole = c.PROPOSER_ROLE();
        bytes32 timelockAdminRole = c.TIMELOCK_ADMIN_ROLE();

        // Grant the executor role to the account to test general role assignment
        // We have executor admin via TIMELOCK_ADMIN_ROLE, but need to prank as admin.
        // For any role, its admin can be obtained. We'll use a role that is not admin-restricted.
        // To generalize: we grant a role to 'account' using 'grantRole' and then check hasRole.
        vm.startPrank(address(this));
        // We can only grant roles where we are the admin.
        // We are admin of PROPOSER_ROLE and EXECUTOR_ROLE (via TIMELOCK_ADMIN_ROLE).
        // We'll grant the proposer role, which we can grant.
        c.grantRole(proposerRole, account);
        vm.stopPrank();

        // The property: for the granted role and account, hasRole must return true.
        // The reference implementation returns true, and the buggy one returns false.
        assertTrue(c.hasRole(proposerRole, account));
    }
}

