// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // Ensure role is not DEFAULT_ADMIN_ROLE and account is not the zero address to keep domain wide
        vm.assume(role != bytes32(0));
        vm.assume(account != address(0));

        // Record hasRole for the given role and for DEFAULT_ADMIN_ROLE via public view
        bool roleMembership = c.hasRole(role, account);
        bool defaultAdminMembership = c.hasRole(bytes32(0), account);

        // General rule: For any non-DEFAULT_ADMIN_ROLE, hasRole must return the stored membership for that role,
        // which is initially false for a random account unless explicitly granted.
        // The bug returns DEFAULT_ADMIN_ROLE membership instead, so the returned value must equal defaultAdminMembership
        // if the bug is present, but can differ in the reference.
        // More concretely, for a random account that has not been granted any role,
        // hasRole(role, account) must equal hasRole(DEFAULT_ADMIN_ROLE, account) in the buggy version.
        // In the reference, they are independent. Since we cannot guarantee they differ without setup,
        // we assert the opposite: the reference always satisfies that hasRole(role, account) equals
        // the actual internal state for that role, while the bug breaks this by returning the wrong storage.
        // To turn this into an assertion that always holds on the reference and fails on the bug,
        // observe that for any role and account, the returned value must equal the value obtained
        // by querying the role's admin role (which is stored independently). We use a trick:
        // grantRole for the requested role to account via a prank as the admin of that role.
        // Since the bug ignores the role parameter, granting a non-DEFAULT_ADMIN_ROLE role will
        // not affect the return value of hasRole for that role in the buggy version (it will still
        // return DEFAULT_ADMIN_ROLE membership), while the reference will reflect the grant.
        // So we first grant the role to account via the role's admin (which is TIMELOCK_ADMIN_ROLE).
        // However, we need the admin of the role, which is TIMELOCK_ADMIN_ROLE.
        // We are the deployer and have TIMELOCK_ADMIN_ROLE, so we can grant any role.
        bytes32 timelockAdminRole = keccak256("TIMELOCK_ADMIN_ROLE");
        vm.prank(address(this));
        c.grantRole(role, account);

        // Now check hasRole for the role and for DEFAULT_ADMIN_ROLE
        bool roleMembershipAfter = c.hasRole(role, account);
        bool defaultAdminMembershipAfter = c.hasRole(bytes32(0), account);

        // Reference: roleMembershipAfter == true, defaultAdminMembershipAfter unchanged.
        // Bug: roleMembershipAfter still equals defaultAdminMembershipAfter (since it reads DEFAULT_ADMIN_ROLE storage),
        // so they will be equal.
        // Thus in the reference, roleMembershipAfter != defaultAdminMembershipAfter (if default was false),
        // but in the bug they are equal. So we can assert that they are not equal.
        // However, if account already had DEFAULT_ADMIN_ROLE, they might be equal even in reference.
        // To avoid that, we assume account does not have DEFAULT_ADMIN_ROLE initially.
        // But we cannot assume that without checking. Instead, we assert that hasRole(role, account) returns true,
        // which the reference satisfies and the bug does not if defaultAdminMembership was false.
        // Since we granted the role, the reference guarantees true. The bug returns defaultAdminMembership,
        // which may be false. Thus assertTrue(roleMembershipAfter) passes on reference, fails on bug if default false.
        // We can ensure defaultAdminMembership is false by choosing an account that hasn't been granted anything.
        // Since account is fuzzed and we only granted role (not DEFAULT_ADMIN_ROLE), defaultAdminMembershipAfter is
        // whatever it was before, likely false for a random account. So we assert:
        assertTrue(roleMembershipAfter);
    }
}

