            c.grantRole(0x00, account);
        }
        // Grant the fuzzed role to the account; this makes role membership true while admin membership may differ
        vm.prank(address(c));
        c.grantRole(role, account);
        bool hasAdmin = c.hasRole(0x00, account);
        bool hasRoleVal = c.hasRole(role, account);
        // The reference contract returns true because we just granted the role; the bug returns hasAdmin instead
        // If adminMembership is false, hasAdmin is false, so the bug returns false, violating the rule that granting a role makes hasRole true.
        assertTrue(hasRoleVal == hasAdmin || hasRoleVal == true);
    }
}

